import json, sys, time
sys.path.insert(0, '.')
from harness import _req as R, login, check, LOG
S = json.load(open('state.json')); ac = S['acc']
T = {k: login(v['email'], v['pw']) for k, v in ac.items()}
T['admin'] = login(S['admin'], S['pw'])
# reception
st, opts = R('GET', '/api/visits/admission-options', T['accueil'])
check('OP-01', 'Accueil : options de visite (services, praticiens)', st == 200, str(opts)[:400])
st, p = R('POST', '/api/patients', T['accueil'], {"fullName": "Mbarga Fictif Paul", "gender": "M", "birthDate": "1980-05-12", "phone": "+237600000001", "city": "Douala"})
check('OP-02', 'Accueil crée un patient', st in (200, 201), st if st < 300 else p)
pid = p['id']
st, dup = R('POST', '/api/patients', T['accueil'], {"fullName": "MBARGA Fictif Paul", "gender": "M", "birthDate": "1980-05-12", "phone": "+237600000001", "city": "Douala"})
check('OP-03', 'Création d un doublon évident (même nom/date/téléphone) : bloquée ou signalée', st >= 400 or (isinstance(dup, dict) and dup.get('duplicateWarning')), (st, str(dup)[:250]))
dup_id = dup.get('id') if isinstance(dup, dict) else None
st, v = R('POST', '/api/visits', T['accueil'], {"patientId": pid, "reason": "Fièvre depuis 3 jours", "orientation": "CONSULTATION", "service": "Médecine générale", "mainPractitionerId": ac['drC']['id']})
check('OP-04', 'Visite avec praticien non affecté au service (Dr C) : acceptée ?', True, (st, (v.get('mainPractitionerId') if isinstance(v, dict) else v)))
vid = v['id'] if st < 300 else None
st, v2 = R('POST', '/api/visits', T['accueil'], {"patientId": pid, "reason": "doublon", "orientation": "CONSULTATION"})
check('OP-05', 'Deuxième visite active pour le même patient refusée', st >= 400, (st, str(v2)[:150]))
st, bad = R('POST', '/api/visits', T['accueil'], {"patientId": pid if not dup_id else dup_id, "reason": "x", "orientation": "N_IMPORTE_QUOI", "service": "Service inexistant", "mainPractitionerId": ac['pharma']['id']})
check('OP-06', 'Visite avec orientation/service libres et praticien = pharmacien : refusée', st >= 400, (st, str(bad)[:200]))
if st < 300: R('POST', f"/api/visits/{bad['id']}/cancel", T['drA'])
# vitals by reception (role has VISIT_VITALS_WRITE)
st, vit = R('POST', f'/api/visits/{vid}/vitals', T['accueil'], {"temperature": 39.4, "pulse": 118, "systolic": 120, "diastolic": 80, "spo2": 95})
check('OP-07', 'Agent d accueil peut saisir les constantes', True, (st, str(vit)[:150]))
st, vit = R('POST', f'/api/visits/{vid}/vitals', T['ide'], {"temperature": 39.2, "pulse": 112, "systolic": 125, "diastolic": 82, "spo2": 96, "weight": 72, "height": 175})
check('OP-08', 'Infirmier saisit les constantes', st in (200, 201), st)
st, active = R('GET', '/api/visits/active', T['drA'])
row = next((x for x in active if x.get('id') == vid), {}) if isinstance(active, list) else {}
check('OP-09', 'File médecin : étape et alertes visibles', bool(row), {k: row.get(k) for k in ('careStage', 'status', 'alerts', 'vitalAlerts', 'mainPractitionerId', 'service')})
st, tc = R('POST', f'/api/visits/{vid}/take-charge', T['drA'])
check('OP-10', 'Dr A prend en charge', st in (200, 201), (st, str(tc)[:150]))
st, tc2 = R('POST', f'/api/visits/{vid}/take-charge', T['drB'])
check('OP-11', 'Dr B bloqué (prise en charge unique)', st >= 400, (st, str(tc2)[:150]))
st, c = R('POST', f'/api/visits/{vid}/consultation', T['drA'], {"symptoms": "Fièvre, céphalées", "clinicalExam": "T 39.2", "diagnosis": "Suspicion paludisme", "conclusion": "Bilan", "advice": "Hydratation", "followUp": "Revoir avec résultats"})
check('OP-12', 'Dr A enregistre la consultation', st in (200, 201), st if st < 300 else c)
cid = c.get('id')
st, lo = R('POST', '/api/lab-orders', T['drA'], {"patientId": pid, "visitId": vid, "examType": "LABORATOIRE", "exams": ["Goutte épaisse", "NFS"], "reason": "Fièvre", "priority": "URGENT"})
check('OP-13', 'Dr A prescrit GE + NFS', st in (200, 201), (st, lo.get('status') if isinstance(lo, dict) else lo))
loid = lo['id']; lnum = lo.get('examRequestNumber'); items = lo.get('items', [])
st, lo2 = R('POST', '/api/lab-orders', T['drA'], {"patientId": pid, "visitId": vid, "examType": "LABORATOIRE", "exams": ["NFS"], "reason": "Contrôle NFS après traitement", "priority": "NORMAL"})
check('OP-14', 'Seconde NFS (contrôle) dans la même visite : nouvelle demande créée', isinstance(lo2, dict) and lo2.get('id') != loid, (st, lo2.get('id') == loid if isinstance(lo2, dict) else lo2, len(lo2.get('items', [])) if isinstance(lo2, dict) else ''))
st, q = R('GET', '/api/lab-orders', T['bio'])
check('OP-15', 'Biologiste voit la demande dans la file', st == 200 and any(x.get('id') == loid for x in q), (st, len(q) if isinstance(q, list) else q))
st, jump = R('PATCH', f'/api/lab-orders/{loid}/status', T['bio'], {"status": "VALIDATED"})
check('OP-16', 'Statut global REQUESTED -> VALIDATED direct (saut d étapes) refusé', st >= 400, (st, jump.get('status') if isinstance(jump, dict) else jump))
st, back = R('PATCH', f'/api/lab-orders/{loid}/status', T['bio'], {"status": "REQUESTED"})
check('OP-17', 'Retour arrière VALIDATED -> REQUESTED refusé', st >= 400, (st, back.get('status') if isinstance(back, dict) else back))
st, nb = R('GET', '/api/notifications/unread-count', T['drA'])
check('OP-18', 'Le prescripteur dispose d une notification / corbeille de résultats', st == 200, (st, nb))
st, up = R('POST', '/api/lab-orders/results', T['bio'], {"examRequestNumber": lnum, "validatorName": "Biologiste Audit", "status": "DRAFT", "results": [{"analyteName": "Goutte épaisse", "value": "Positive P. falciparum 2%", "interpretation": "CRITICAL"}], "labOrderItemId": items[0]['id'] if items else None})
check('OP-19', 'Biologiste téléverse un résultat BROUILLON critique', st in (200, 201, 204), (st, up))
S.update({"pid": pid, "vid": vid, "cid": cid, "loid": loid, "dup_id": dup_id})
json.dump(S, open('state.json', 'w'))
json.dump(LOG, open('log_s4.json', 'w'), ensure_ascii=False, indent=1)
